/* Depósitos locais integrados ao catálogo existente, sem distribuição automática de saldos. */
(()=>{'use strict';const D=MartinsDepositos,P=MartinsPersistenciaRdo,J=MartinsJornada,$=id=>document.getElementById(id),host=$('painel-sup-estoque-depositos');if(!host)return;
const panel=document.createElement('section');panel.id='dp-panel';panel.className='mf-box';panel.innerHTML='<h3>Depósitos e localização dos materiais</h3><p>O saldo global existente permanece preservado. Materiais sem movimentação para um local ficam em “Sem localização definida”. Cadastrar ou vincular um depósito não move estoque. Entrada/saída muda o total global; localização/transferência conserva o total. Não lança despesa nem consumo no RDO.</p><button id="dp-new" type="button">+ Cadastrar depósito</button><button id="dp-transfer" type="button">Localizar / transferir material</button><button id="dp-refresh" type="button">Atualizar depósitos e saldos</button><details id="dp-editor"><summary style="font-weight:800;cursor:pointer">Cadastro / edição de depósito</summary><div class="mf-grid"><label>Nome do depósito<input id="dp-name" maxlength="200"></label><label>Local / endereço<input id="dp-local" maxlength="200"></label><label>Responsável pelo depósito<input id="dp-person" maxlength="200"></label><label>Situação<select id="dp-active"><option value="true">Ativo</option><option value="false">Inativo</option></select></label></div><p>Obras vinculadas ao depósito:</p><div id="dp-work-checks" style="max-height:220px;overflow:auto"></div><button id="dp-save" type="button">Conferir cadastro</button><button id="dp-cancel-edit" type="button">Cancelar edição</button></details><div id="dp-list"></div><details id="dp-movement"><summary style="font-weight:800;cursor:pointer">Localização / transferência</summary><p>Para localizar saldo antigo, escolha Sem localização definida como origem e o depósito como destino. Use a unidade de compra do produto.</p><label>Produto<select id="dp-product"></select></label><div class="mf-grid"><label>Origem<select id="dp-from"></select></label><label>Destino<select id="dp-to"></select></label><label>Quantidade (unidade de compra)<input id="dp-quantity" type="number" step="0.000001" min="0.000001" inputmode="decimal"></label><label>Data<input id="dp-date" type="date"></label></div><label>Motivo / referência<input id="dp-note" maxlength="500"></label><button id="dp-prepare" type="button">Conferir transferência</button></details><p id="dp-status" class="mf-message" role="status"></p><details><summary style="font-weight:800;cursor:pointer">Histórico das movimentações registradas nesta etapa</summary><div id="dp-history"></div></details>';host.append(panel);
const note=document.createElement('p');note.id='dp-stock-note';note.className='text-xs text-slate-600';host.prepend(note);const access=document.createElement('button');access.type='button';access.className='gm-action';access.textContent='Cadastrar / gerenciar depósitos';access.onclick=()=>{refresh();panel.scrollIntoView({block:'start'});};$('sup-estoque-deposito-select')?.parentElement.append(access);
const style=document.createElement('style');style.textContent='#dp-panel label input[type=checkbox]{width:auto;display:inline-block;margin-right:8px}#dp-list>div{padding:12px 0;border-top:1px solid #cbd5e1}#dp-history p,#dp-work-rows p{font-size:12px;line-height:1.6}#dp-dialog{width:min(620px,calc(100vw - 20px));max-height:88vh;overflow:auto;border:1px solid #cbd5e1;border-radius:14px;padding:20px}#dp-dialog::backdrop{background:#020617bb}#dp-review{white-space:pre-wrap;font-size:12px}#dp-dialog button{padding:11px;min-height:44px;border-radius:8px;background:#0f172a;color:#fbbf24;margin:5px;font-weight:700;font-size:12px}#dp-dialog-message{color:#92400e;white-space:pre-wrap}@media print{#dp-panel,#subview-depositos{display:none!important}}';document.head.append(style);
const workPanel=document.createElement('section');workPanel.id='subview-depositos';workPanel.className='mf-box hidden';workPanel.innerHTML='<h3>Depósitos da obra</h3><p id="dp-work-name"></p><p>Vínculo logístico com a obra. Saldo de um depósito compartilhado não é reserva exclusiva para uma obra e não é gasto financeiro.</p><button id="dp-work-refresh" type="button">Atualizar depósitos da obra</button><div id="dp-work-rows"></div>';$('subview-custos')?.after(workPanel);const tab=document.createElement('button');tab.type='button';tab.id='subtab-btn-depositos';tab.className='subtab-btn px-3 py-1.5 text-xs font-medium text-slate-600 rounded-md';tab.textContent='📦 Depósitos da obra';$('subtab-btn-custos')?.after(tab);
const oldTab=window.setSubtabGestao;window.setSubtabGestao=function(name){oldTab(name);workPanel.classList.toggle('hidden',name!=='depositos');tab.classList.toggle('bg-white',name==='depositos');if(name==='depositos')renderWork();};tab.onclick=()=>window.setSubtabGestao('depositos');tab.parentElement?.addEventListener('click',e=>{if(e.target.closest('.subtab-btn')&&e.target.closest('.subtab-btn')!==tab){workPanel.classList.add('hidden');tab.classList.remove('bg-white');}});
const dialog=document.createElement('dialog');dialog.id='dp-dialog';dialog.setAttribute('aria-label','Conferir depósito ou movimento');dialog.innerHTML='<h3 style="font-weight:800">Conferir operação</h3><p id="dp-review"></p><p id="dp-dialog-message" role="status"></p><button id="dp-confirm" type="button">Confirmar registro</button><button id="dp-back" type="button">Voltar sem alterar</button>';document.body.append(dialog);
const movLabel=document.createElement('label');movLabel.className='block font-bold text-slate-700';movLabel.innerHTML='Local da entrada / saída<select id="dp-mov-place" class="w-full border border-slate-300 rounded-lg p-2"></select>';$('mov-produto-select')?.parentElement.after(movLabel);if($('mov-inp-qtd')){$('mov-inp-qtd').step='0.000001';$('mov-inp-qtd').min='0.000001';}let editor=null,movementBase=null,request=null,busy=false;const num=n=>Number(n).toLocaleString('pt-BR',{maximumFractionDigits:6}),money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),today=()=>new Date().toLocaleDateString('en-CA');
function actor(){let session;try{session=JSON.parse(sessionStorage.getItem('cm_active_user')||'null');}catch{}const u=currentLoggedUser,id=x=>String(x?.id||x?.usuario||x?.email||'');if(!D.canManage(u)||!session||!id(u)||id(u)!==id(session)||u.perfil!==session.perfil||session.status==='Inativo')throw Error('Entre com perfil autorizado ao estoque/depósitos.');return u.usuario||u.email||u.nome;}
function sources(){const p=P.snapshot(localStorage,D.CATALOG,INITIAL_PRODUTOS_FATOR),d=P.snapshot(localStorage,D.DEPOTS,[]),m=P.snapshot(localStorage,D.MOVES,[]),w=P.snapshot(localStorage,'cm_dados_obras_v2',dadosObras);return {p,d,m,w,state:D.validate(p.data,d.data,m.data)};}
function signature(s){return P.canonical([s.p.raw,s.d.raw,s.m.raw,s.w.raw]);}
function options(select,rows,first){if(!select)return;const before=select.value;select.replaceChildren();if(first)select.add(new Option(first.label,first.value));for(const r of rows)select.add(new Option(r.label,r.value));if([...select.options].some(o=>o.value===before))select.value=before;}
function placeName(id,s){return id===D.EXTERNAL?'Entrada / saída externa':id?s.d.data.find(d=>d.id===id)?.nome||'Depósito indisponível':'Sem localização definida';}
function depotOptions(s,activeOnly=true){return s.d.data.filter(d=>!activeOnly||d.ativo).map(d=>({label:d.nome+(d.ativo?'':' (inativo)'),value:d.id}));}
function fillPlaces(s){options($('sup-estoque-deposito-select'),[{label:'Sem localização definida',value:'@unassigned'},...depotOptions(s,false)],{label:'Total geral — todos os locais',value:'@global'});for(const id of ['dp-from','dp-to','dp-mov-place'])options($(id),depotOptions(s),{label:'Sem localização definida',value:''});options($('dp-product'),s.p.data.filter(p=>p.ativo!==false).map(p=>({label:p.nome+' — '+p.unCompra,value:p.id})),{label:'Selecione produto',value:''});}
function renderStock(s){fillPlaces(s);const scope=$('sup-estoque-deposito-select').value,tbody=$('tbody-estoque-depositos');tbody.replaceChildren();let total=0,unknown=0;for(const p of s.p.data){const quantity=scope==='@global'?Number(p.estoqueCompra):D.balance(s.state,p.id,scope==='@unassigned'?'':scope),cost=Number(p.precoCompra),known=p.precoCompra!==undefined&&p.precoCompra!==null&&p.precoCompra!==''&&Number.isFinite(cost)&&cost>=0;if(known)total+=Math.round(quantity*cost*100);else unknown++;const tr=document.createElement('tr');for(const v of [p.nome+' / '+(p.codigo||p.id),p.unCompra,p.fatorEmb!==undefined&&p.fatorEmb!==null&&p.fatorEmb!==''?p.fatorEmb+' '+(p.unFator||''):'Não informado',num(quantity),p.fatorEmb!==undefined&&p.fatorEmb!==null&&p.fatorEmb!==''&&Number.isFinite(Number(p.fatorEmb))?num(quantity*Number(p.fatorEmb))+' '+(p.unFator||''):'Não informado',known?money(cost):'Não informado',p.precoVenda!==undefined&&p.precoVenda!==null&&p.precoVenda!==''&&Number.isFinite(Number(p.precoVenda))?money(p.precoVenda):'Não informado',known?money(Math.round(quantity*cost*100)/100):'Não informado']){const td=document.createElement('td');td.className='p-3';td.textContent=v;tr.append(td);}const td=document.createElement('td');for(const [type,label] of [['entrada','+ Entrada'],['saida','− Saída']]){const b=document.createElement('button');b.type='button';b.className='gm-action';b.textContent=label;b.onclick=()=>window.abrirModalMovimentoEstoque(type,p.id);td.append(b);}tr.append(td);tbody.append(tr);}$('stat-estoque-total-itens').textContent=s.p.data.length+' produtos no catálogo';$('stat-estoque-valor-total').textContent=money(total/100)+(unknown?' · '+unknown+' sem preço':'');note.textContent=(scope==='@global'?'Total global preservado':scope==='@unassigned'?'Saldo ainda sem localização':placeName(scope,s))+' · Valor exibido estimado ao preço de compra cadastrado. Entrada e saída usam o local escolhido no formulário.';}
window.renderEstoqueDepositosMartins=function(){try{P.guard(localStorage,D.CATALOG);renderStock(sources());}catch(e){$('tbody-estoque-depositos').replaceChildren();$('stat-estoque-total-itens').textContent='Consulta indisponível';$('stat-estoque-valor-total').textContent='';note.textContent=e.message;}};
const oldSave=window.saveProdutosFatorDb;window.saveProdutosFatorDb=function(rows){const s=sources();D.validate(rows,s.d.data,s.m.data);P.guard(localStorage,D.CATALOG);return oldSave(rows);};
function renderWork(){const box=$('dp-work-rows');box.replaceChildren();try{const s=sources(),work=$('gestao-obra-select').value;$('dp-work-name').textContent='Obra: '+work;const linked=s.d.data.filter(d=>d.obras.includes(work));for(const d of linked){const p=document.createElement('p');p.textContent=d.nome+' · '+d.local+' · responsável: '+d.responsavel+' · '+(d.ativo?'Ativo':'Inativo')+' · Obras vinculadas: '+d.obras.join(', ');box.append(p);const table=document.createElement('table');table.className='w-full';for(const product of s.p.data){const q=D.balance(s.state,product.id,d.id);if(!q)continue;const row=document.createElement('tr');for(const text of [product.nome,num(q)+' '+product.unCompra]){const td=document.createElement('td');td.className='p-2 text-xs';td.textContent=text;row.append(td);}table.append(row);}box.append(table);}if(!linked.length)box.textContent='Nenhum depósito vinculado à obra selecionada.';}catch(e){box.textContent=e.message;}}
function refresh(){try{const s=sources();renderStock(s);$('dp-list').replaceChildren();for(const d of s.d.data){const box=document.createElement('div'),p=document.createElement('p');p.textContent=d.nome+' · '+d.local+' · '+d.responsavel+' · '+(d.ativo?'Ativo':'Inativo')+' · Obras: '+(d.obras.join(', ')||'nenhuma');box.append(p);const b=document.createElement('button');b.type='button';b.textContent='Editar depósito / vínculos';b.onclick=()=>edit(d.id);box.append(b);const detail=document.createElement('details'),sum=document.createElement('summary'),history=document.createElement('p');sum.textContent='Histórico do cadastro';history.textContent=d.historico.map(h=>h.acao+' por '+h.por+' em '+h.em).join('; ');detail.append(sum,history);box.append(detail);$('dp-list').append(box);}$('dp-history').replaceChildren();for(const m of s.m.data.slice().reverse()){const p=document.createElement('p');p.textContent=m.data.split('-').reverse().join('/')+' · '+m.tipo+' · '+m.produtoNome+' · '+num(m.quantidade)+' '+m.unidade+' · '+placeName(m.origem,s)+' → '+placeName(m.destino,s)+' · '+m.por+' · '+m.observacao;$('dp-history').append(p);}if(!s.m.data.length)$('dp-history').textContent='Sem movimentações por local nesta etapa.';renderWork();$('dp-status').textContent='Consulta atualizada. Nenhum saldo foi localizado automaticamente.';}catch(e){$('dp-status').textContent=e.message;}}
function edit(id=null){try{actor();P.guard(localStorage,D.DEPOTS);const s=sources(),d=id?s.d.data.find(d=>d.id===id):null;if(id&&!d)throw Error('Depósito ausente');editor={id,expected:signature(s)};$('dp-name').value=d?.nome||'';$('dp-local').value=d?.local||'';$('dp-person').value=d?.responsavel||'';$('dp-active').value=String(d?.ativo!==false);$('dp-work-checks').replaceChildren();for(const name of [...new Set([...Object.keys(s.w.data),...(d?.obras||[])])].sort()){const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.value=name;check.checked=Boolean(d?.obras.includes(name));label.append(check,document.createTextNode(name+(Object.hasOwn(s.w.data,name)?'':' (obra indisponível; revise o vínculo)')));$('dp-work-checks').append(label);}$('dp-editor').open=true;$('dp-editor').scrollIntoView({block:'start'});}catch(e){$('dp-status').textContent=e.message;}}
function review(text){$('dp-review').textContent=text;$('dp-dialog-message').textContent='';dialog.showModal();}
$('dp-new').onclick=()=>edit();$('dp-cancel-edit').onclick=()=>{editor=null;$('dp-editor').open=false;};$('dp-save').onclick=()=>{try{const by=actor(),s=sources();if(!editor||editor.expected!==signature(s))throw Error('Dados mudaram; reabra a edição');const input={nome:$('dp-name').value,local:$('dp-local').value,responsavel:$('dp-person').value,ativo:$('dp-active').value==='true',obras:[...$('dp-work-checks').querySelectorAll('input:checked')].map(x=>x.value)},id=editor.id||'DEP-'+P.newId();D.saveDepot(s.d.data,s.m.data,s.p.data,editor.id,input,Object.keys(s.w.data),by,{newId:id});request={kind:'depot',input,id,oldId:editor.id,expected:signature(s)};review(input.nome+'\n'+input.local+'\nResponsável: '+input.responsavel+'\nObras: '+(input.obras.join(', ')||'nenhuma')+'\n'+(input.ativo?'Ativo':'Inativo')+'\nCadastrar/vincular não movimenta materiais.');}catch(e){$('dp-status').textContent=e.message;}};
function movementRequest(input,expected,closeOld=false){const by=actor(),s=sources();if(expected!==signature(s))throw Error('Estoque alterado; atualize e confira novamente');const id=P.newId(),next=D.plan(s.p.data,s.d.data,s.m.data,input,by,{id}),p=s.p.data.find(p=>p.id===input.produtoId);request={kind:'movement',input,id,expected,closeOld};review(input.tipo.toUpperCase()+' · '+p.nome+'\n'+num(input.quantidade)+' '+p.unCompra+'\n'+placeName(next.entry.origem,s)+' → '+placeName(next.entry.destino,s)+'\nTotal global: '+num(p.estoqueCompra)+' → '+num(next.products.find(p=>p.id===input.produtoId).estoqueCompra)+' '+p.unCompra+'\nNão gera gasto no Financeiro, consumo ou texto no RDO.');}
$('dp-transfer').onclick=()=>{try{actor();const s=sources();fillPlaces(s);movementBase=signature(s);$('dp-movement').open=true;$('dp-movement').scrollIntoView({block:'start'});}catch(e){$('dp-status').textContent=e.message;}};$('dp-prepare').onclick=()=>{try{movementRequest({tipo:'transferencia',produtoId:$('dp-product').value,origem:$('dp-from').value,destino:$('dp-to').value,quantidade:$('dp-quantity').value,data:$('dp-date').value,observacao:$('dp-note').value},movementBase);}catch(e){$('dp-status').textContent=e.message;}};
const oldOpen=window.abrirModalMovimentoEstoque;window.abrirModalMovimentoEstoque=function(type,id){try{actor();const s=sources();fillPlaces(s);oldOpen(type,id);const scope=$('sup-estoque-deposito-select').value;$('dp-mov-place').value=scope==='@global'||scope==='@unassigned'?'':scope;movementBase=signature(s);}catch(e){showToast(e.message,'warning');}};
window.salvarMovimentoEstoqueForm=function(e){e?.preventDefault();try{movementRequest({tipo:$('mov-tipo').value,produtoId:$('mov-produto-select').value,deposito:$('dp-mov-place').value,quantidade:$('mov-inp-qtd').value,data:today(),observacao:$('mov-inp-destino').value},movementBase,true);}catch(error){showToast(error.message,'warning');}};
const oldProductSave=window.salvarProdutoFatorForm;window.salvarProdutoFatorForm=function(...args){const before=localStorage.getItem(D.CATALOG),previous=movementBase;const result=oldProductSave.apply(this,args);try{if(previous&&localStorage.getItem(D.CATALOG)!==before){const expected=JSON.parse(previous),s=sources();if(expected[0]===before&&expected[1]===s.d.raw&&expected[2]===s.m.raw&&expected[3]===s.w.raw)movementBase=signature(s);}}catch{movementBase=null;}return result;};
$('dp-confirm').onclick=async()=>{if(busy||!request)return;busy=true;const req=structuredClone(request);$('dp-confirm').disabled=true;$('dp-back').disabled=true;let saved=false;try{await P.withLock(navigator.locks,()=>{const by=actor(),s=sources();if(req.expected!==signature(s))throw Error('Dados alterados após a conferência. Reabra a operação.');let writes;if(req.kind==='depot'){const rows=D.saveDepot(s.d.data,s.m.data,s.p.data,req.oldId,req.input,Object.keys(s.w.data),by,{newId:req.id});writes=[{key:D.DEPOTS,value:rows,expected:s.d.raw}];}else{const next=D.plan(s.p.data,s.d.data,s.m.data,req.input,by,{id:req.id});writes=[{key:D.MOVES,value:next.moves,expected:s.m.raw}];if(P.canonical(next.products)!==P.canonical(s.p.data))writes.push({key:D.CATALOG,value:next.products,expected:s.p.raw});}P.commit(localStorage,writes,{actor:by});saved=true;});dialog.close();request=null;if(req.kind==='depot'){editor=null;$('dp-editor').open=false;}else{$('dp-quantity').value='';$('dp-movement').open=false;if(req.closeOld)window.fecharModalMovimentoEstoque?.();}refresh();$('dp-status').textContent='Operação registrada com histórico e saldos preservados.';try{window.renderTabelaProdutosFator?.();}catch{}}catch(e){$('dp-dialog-message').textContent=(saved?'Operação salva; atualize antes de repetir. ':'')+e.message;if(P.hasPending(localStorage)){dialog.close();window.martinsMostrarRecuperacao?.();}}finally{busy=false;$('dp-confirm').disabled=false;$('dp-back').disabled=false;}};
$('dp-back').onclick=()=>{if(!busy)dialog.close();};dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});dialog.addEventListener('close',()=>{if(!busy)request=null;});$('dp-refresh').onclick=refresh;$('dp-work-refresh').onclick=renderWork;$('gestao-obra-select')?.addEventListener('change',renderWork);window.addEventListener('storage',e=>{if([D.DEPOTS,D.MOVES,D.CATALOG].includes(e.key)){$('dp-status').textContent='Dados alterados em outra aba; atualize a consulta.';movementBase=null;}});$('dp-date').value=today();document.addEventListener('DOMContentLoaded',refresh);refresh();
})();
